// ---- fetch shim (ESM-safe, no deps) ----
(function fetchShimESM(){
  if (typeof (globalThis as any).fetch === "function") return;
  (globalThis as any).fetch = async (url:string, opts:any={})=>{
    const u = new URL(url);
    const mod = u.protocol === "https:" ? await import("node:https") : await import("node:http");
    const headersIn = opts.headers || {};
    return await new Promise((resolve,reject)=>{
      const req = mod.request({
        method: opts.method || "GET",
        hostname: u.hostname,
        port: u.port || (u.protocol==="https:"?443:80),
        path: (u.pathname||"/") + (u.search||""),
        headers: headersIn
      }, (res:any)=>{
        const chunks:any[]=[]; res.on("data",(c:any)=>chunks.push(c));
        res.on("end",()=>{
          const buf = Buffer.concat(chunks); const text = buf.toString("utf8");
          resolve({
            ok: (res.statusCode>=200 && res.statusCode<300),
            status: res.statusCode,
            headers: res.headers,
            text: async()=>text,
            json: async()=>{ try{return JSON.parse(text);}catch{ return null; } }
          });
        });
      });
      req.on("error", reject);
      if (opts.body) req.write(opts.body);
      req.end();
    });
  };
})();
