    // VOID_PUBLIC_BUY_VOID_REQUEST_INTAKE_V1
    function __voidBuyVoidConfigV1(){
      const receive_address = String(process.env.VOID_BUY_RECEIVE_ADDRESS || process.env.VOID_USDC_RECEIVER || "").trim();
      const chain = String(process.env.VOID_BUY_CHAIN || "base").trim();
      const usdc_symbol = String(process.env.VOID_BUY_USDC_SYMBOL || "USDC").trim();
      const rate_void_per_usdc = Number(process.env.VOID_BUY_RATE_VOID_PER_USDC || "2");
      const min_usdc = Number(process.env.VOID_BUY_MIN_USDC || "1");
      const max_usdc = Number(process.env.VOID_BUY_MAX_USDC || "500");
      const requests_enabled = String(process.env.VOID_BUY_REQUESTS_ENABLED || "1") !== "0";
      const payment_ready = /^0x[a-fA-F0-9]{40}$/.test(receive_address);
      return {
        schema: "void_public_buy_void_config_v1",
        ok: true,
        mode: "guarded_request_intake",
        requests_enabled,
        payment_ready,
        chain,
        usdc_symbol,
        receive_address: payment_ready ? receive_address : "",
        rate_void_per_usdc,
        price_usdc_per_void: Number(process.env.VOID_BUY_PRICE_USDC_PER_VOID || "0.50"),
        pool_void_total: Number(process.env.VOID_BUY_POOL_VOID_TOTAL || "10000000"),
        max_raise_usdc: Number(process.env.VOID_BUY_MAX_RAISE_USDC || "5000000"),
        min_usdc,
        max_usdc,
        asset_in: "USDC",
        asset_out: "VOID",
        automatic_fulfillment: false,
        manual_review_required: true,
        no_investment_return_promised: true,
        no_automatic_token_delivery_promised: true,
        do_not_send_from_exchange: true
      };
    }

    // VOID_BUY_VOID_POOL_ACCOUNTING_V1
    async function __voidBuyVoidSaleStateV1(){
      const fs = await import("node:fs");
      const path = await import("node:path");
      const dir = String(process.env.VOID_BUY_REQUEST_DIR || ".runtime/public-buy-void-requests-v1");
      const pool_void_total = Number(process.env.VOID_BUY_POOL_VOID_TOTAL || "10000000");
      const price_usdc_per_void = Number(process.env.VOID_BUY_PRICE_USDC_PER_VOID || "0.50");
      const rate_void_per_usdc = Number(process.env.VOID_BUY_RATE_VOID_PER_USDC || "2");
      const max_raise_usdc = Math.floor((pool_void_total * price_usdc_per_void) * 1e6) / 1e6;

      let requested_usdc_total = 0;
      let requested_void_total = 0;
      let submitted_usdc_total = 0;
      let submitted_void_total = 0;
      let request_count = 0;
      let submitted_tx_count = 0;

      // VOID_BUY_VOID_VERIFIED_ONLY_POOL_RESERVATION_V1
      const verifiedIds = new Set();
      const eventsJsonl = path.join(dir, "operator-events.jsonl");
      if (fs.existsSync(eventsJsonl)) {
        const eventLines = fs.readFileSync(eventsJsonl, "utf8").split(/\n+/).filter(Boolean);
        for (const line of eventLines) {
          try {
            const e = JSON.parse(line);
            if (e && e.request_id && e.operator_status === "payment_verified") {
              verifiedIds.add(String(e.request_id));
            }
          } catch (err) { voidIndexEmptyCatchVisibilityWindow17101_18000V1("17447:3", err); }
        }
      }

      const jsonl = path.join(dir, "requests.jsonl");
      if (fs.existsSync(jsonl)) {
        const lines = fs.readFileSync(jsonl, "utf8").split(/\n+/).filter(Boolean);
        const seen = new Set();
        for (const line of lines) {
          try {
            const j = JSON.parse(line);
            if (!j || !j.request_id || seen.has(j.request_id)) continue;
            seen.add(j.request_id);
            const usdc = Number(j.usdc_amount || 0);
            const quoted = Number(j.quoted_void || 0);
            if (!Number.isFinite(usdc) || !Number.isFinite(quoted) || usdc <= 0 || quoted <= 0) continue;
            request_count++;
            requested_usdc_total += usdc;
            requested_void_total += quoted;
            if (verifiedIds.has(String(j.request_id || ""))) {
              submitted_tx_count++;
              submitted_usdc_total += usdc;
              submitted_void_total += quoted;
            }
          } catch (err) { voidIndexEmptyCatchVisibilityWindow17101_18000V1("17471:4", err); }
        }
      }

      // VOID_BUY_VOID_PAID_ONLY_POOL_RESERVATION_V1
      // Unpaid quote/request records and unverified tx-hash submissions do not reserve presale capacity.
      // Available presale inventory is reduced only after operator_status === "payment_verified".
      const reserved_void = Math.min(pool_void_total, submitted_void_total);
      const remaining_void = Math.max(0, Math.floor((pool_void_total - reserved_void) * 1e6) / 1e6);
      const raised_usdc_reported = Math.floor(submitted_usdc_total * 1e6) / 1e6;
      const requested_usdc = Math.floor(requested_usdc_total * 1e6) / 1e6;
      const requested_void = Math.floor(requested_void_total * 1e6) / 1e6;
      const submitted_void = Math.floor(submitted_void_total * 1e6) / 1e6;
      const sold_out = remaining_void <= 0.000001;
      const progress_pct = pool_void_total > 0 ? Math.floor((reserved_void / pool_void_total) * 10000) / 100 : 0;

      return {
        schema: "void_buy_void_sale_state_v1",
        ok: true,
        pool_void_total,
        price_usdc_per_void,
        rate_void_per_usdc,
        max_raise_usdc,
        requested_usdc_total: requested_usdc,
        requested_void_total: requested_void,
        submitted_usdc_total: raised_usdc_reported,
        submitted_void_total: submitted_void,
        raised_usdc_so_far: raised_usdc_reported,
        verified_usdc_total: raised_usdc_reported,
        verified_void_total: submitted_void,
        allocation_reserved_void: reserved_void,
        request_count,
        submitted_tx_count,
        remaining_void,
        sold_out,
        progress_pct,
        cutoff_rule: "buy_void_hidden_and_requests_rejected_when_verified_payment_reserved_void_reaches_presale_limit",
        accounting_note: "unpaid and unverified tx-submitted requests are quotes only; only payment_verified operator events may reserve presale allocation"
      };
    }

    // VOID_BUY_VOID_OPERATOR_QUEUE_V1
    async function __voidReadBuyVoidRequestsV1(){
      const fs = await import("node:fs");
      const path = await import("node:path");
      const dir = String(process.env.VOID_BUY_REQUEST_DIR || ".runtime/public-buy-void-requests-v1");
      const jsonl = path.join(dir, "requests.jsonl");
      const out:any[] = [];
      const seen = new Set();

      if (!fs.existsSync(jsonl)) return out;

      const lines = fs.readFileSync(jsonl, "utf8").split(/\n+/).filter(Boolean);
      for (const line of lines) {
        try {
          const j:any = JSON.parse(line);
          if (!j || !j.request_id || seen.has(j.request_id)) continue;
          seen.add(j.request_id);
          out.push(j);
        } catch (err) { voidIndexEmptyCatchVisibilityWindow17101_18000V1("17530:5", err); }
      }

      out.sort((a:any,b:any)=>Number(b.created_at_ms||0)-Number(a.created_at_ms||0));
      return out;
    }

    function __voidBuyVoidOperatorLocalOnlyV1(req:any,res:any){
      const host = String(req.headers?.host || "");
      const remote = String(req.socket?.remoteAddress || "");
      const localHost = host.startsWith("127.0.0.1:") || host.startsWith("localhost:");
      const localRemote = remote === "127.0.0.1" || remote === "::1" || remote === "::ffff:127.0.0.1";
      if (localHost || localRemote) return true;
      res.status(403).json({
        schema: "void_buy_void_operator_auth_v1",
        ok: false,
        error: "operator_queue_local_only"
      });
      return false;
    }

    // VOID_BUY_VOID_OPERATOR_MARK_V1
    async function __voidReadBuyVoidOperatorEventsV1(){
      const fs = await import("node:fs");
      const path = await import("node:path");
      const dir = String(process.env.VOID_BUY_REQUEST_DIR || ".runtime/public-buy-void-requests-v1");
      const jsonl = path.join(dir, "operator-events.jsonl");
      const events:any[] = [];
      if (!fs.existsSync(jsonl)) return events;

      for (const line of fs.readFileSync(jsonl, "utf8").split(/\n+/).filter(Boolean)) {
        try {
          const j:any = JSON.parse(line);
          if (j && j.request_id && j.operator_status) events.push(j);
        } catch (err) { voidIndexEmptyCatchVisibilityWindow17101_18000V1("17564:6", err); }
      }

      events.sort((a:any,b:any)=>Number(b.marked_at_ms||0)-Number(a.marked_at_ms||0));
      return events;
    }

    async function __voidWriteBuyVoidOperatorEventV1(event:any){
      const fs = await import("node:fs");
      const path = await import("node:path");
      const dir = String(process.env.VOID_BUY_REQUEST_DIR || ".runtime/public-buy-void-requests-v1");
      fs.mkdirSync(dir, { recursive: true });
      fs.appendFileSync(path.join(dir, "operator-events.jsonl"), JSON.stringify(event) + "\n");
      fs.writeFileSync(path.join(dir, "operator-event-" + event.request_id + "-" + event.marked_at_ms + ".json"), JSON.stringify(event, null, 2));
      return { ok:true, dir };
    }

    // VOID_BUY_VOID_OPERATOR_QUEUE_APPLY_EVENTS_V1
    function __voidApplyBuyVoidOperatorEventsV1(requests:any[], events:any[]){
      const latest = new Map();
      for (const e of events) {
        const id = String(e.request_id || "");
        if (id && !latest.has(id)) latest.set(id, e);
      }

      return requests.map((r:any)=>{
        const id = String(r.request_id || "");
        const e = latest.get(id);
        const hasTx = /^0x[a-fA-F0-9]{64}$/.test(String(r.tx_hash || ""));
        const baseStatus = hasTx ? "payment_submitted_pending_manual_review" : "awaiting_payment";
        const effective_status = e ? String(e.operator_status || baseStatus) : baseStatus;
        return {
          ...r,
          effective_status,
          operator_event: e || null
        };
      });
    }

