          if (age < verifyCooldownMs) continue;
          if (age > maxPickStaleMs) continue;

          const isOwnedProofDataset = isProofAccount && owned.has(datasetId);
          const isFreshUnverifiedProofDataset = isOwnedProofDataset && last <= 0 && fileMtimeMs > 0;
