  async function waitForRedeemableIncrease(account, beforeRedeemable, timeoutMs){
    const started = Date.now();
    const baseline = Number.isFinite(Number(beforeRedeemable)) ? Number(beforeRedeemable) : 0;
    const deadline = started + (Number.isFinite(Number(timeoutMs)) ? Number(timeoutMs) : 12000);
    let last = null;

    while (Date.now() < deadline) {
      try {
        const st = await j("/wc/redeemable?account=" + encodeURIComponent(account));
        last = st;
        const nowRedeemable = st && st.ok ? Number(st.redeemable || 0) : NaN;
        if (Number.isFinite(nowRedeemable) && nowRedeemable > baseline) {
          return {
            ok: true,
            waited_ms: Date.now() - started,
            before_redeemable: baseline,
            after_redeemable: nowRedeemable,
            state: st
          };
        }
      } catch (_) { voidIndexEmptyCatchVisibilityWindow59401_78300V1("70254:126", _); }
      await new Promise(r => setTimeout(r, 500));
    }

    let finalRedeemable = baseline;
    try {
      if (last && last.ok) finalRedeemable = Number(last.redeemable || 0);
    } catch (_) { voidIndexEmptyCatchVisibilityWindow59401_78300V1("70261:127", _); }

    return {
      ok: false,
      waited_ms: Date.now() - started,
      before_redeemable: baseline,
      after_redeemable: finalRedeemable,
      state: last
    };
  }

  function deriveParticipantWallet(account, redeemedState, connectedWallet, manualWallet){
    try {
      const events = redeemedState && Array.isArray(redeemedState.events) ? redeemedState.events : [];
      for (const ev of events) {
        const w = String((ev && ev.wallet) || "").trim();
        if (isWalletAddr(w)) return w;
      }
    } catch (_) { voidIndexEmptyCatchVisibilityWindow59401_78300V1("70279:128", _); }

    if (isWalletAddr(connectedWallet)) return String(connectedWallet).trim();
    if (isWalletAddr(manualWallet)) return String(manualWallet).trim();
    if (isWalletAddr(account)) return String(account).trim();
    return "";
  }

  function shortAddr(a){
    a = String(a || "").trim();
    return /^0x[a-fA-F0-9]{40}$/.test(a) ? (a.slice(0, 6) + "…" + a.slice(-4)) : "-";
  }

  function pad64(hex){
    return String(hex || "").replace(/^0x/, "").padStart(64, "0");
  }

  function parseHexBigInt(hex){
    const s = String(hex || "0x0").trim();
    if (!/^0x[0-9a-fA-F]+$/.test(s)) return 0n;
    return BigInt(s);
  }

  function formatUnits18FromHex(hex){
    try {
      const n = parseHexBigInt(hex);
      const whole = n / (10n ** 18n);
      const frac = n % (10n ** 18n);
      if (frac === 0n) return whole.toString();
      const fracStr = frac.toString().padStart(18, "0").replace(/0+$/, "");
      return whole.toString() + "." + fracStr.slice(0, 6);
    } catch (_) {
      return "-";
    }
  }


