  function parseUnits18(v){
    const s = String(v || "").trim();
    const m = s.match(/^(\d+)(?:\.(\d+))?$/);
    if (!m) throw new Error("invalid_amount");
    const whole = BigInt(m[1] || "0");
    const fracRaw = String(m[2] || "");
    const frac = (fracRaw + "000000000000000000").slice(0, 18);
    return (whole * (10n ** 18n)) + BigInt(frac || "0");
  }

  function erc20TransferData(to, amountUnits){
    const selector = "a9059cbb";
    const addr = String(to || "").replace(/^0x/, "").toLowerCase();
    const amt = amountUnits.toString(16);
    return "0x" + selector + addr.padStart(64, "0") + amt.padStart(64, "0");
  }

  function erc20ApproveData(spender, amountUnits){
    const selector = "095ea7b3";
    const addr = String(spender || "").replace(/^0x/, "").toLowerCase();
    const amt = amountUnits.toString(16);
    return "0x" + selector + addr.padStart(64, "0") + amt.padStart(64, "0");
  }

  async function sendVoidNow(){
    const toInput = $("voidSendTo");
    const amountInput = $("voidSendAmount");
    const to = toInput ? String(toInput.value || "").trim() : "";
    const amountStr = amountInput ? String(amountInput.value || "").trim() : "";
    const btn = $("voidSendBtn");
    const prevText = btn ? btn.textContent : "Send VOID";

    try {
      const nativeSignerStatus = await j("/__void/participant/wallet/status?account=" + encodeURIComponent(resolveActiveParticipantAccount())).catch(() => ({ ok:false }));
      const from = (nativeSignerStatus && nativeSignerStatus.ok && nativeSignerStatus.unlocked && /^0x[a-fA-F0-9]{40}$/.test(String(nativeSignerStatus.address || "").trim()))
        ? String(nativeSignerStatus.address || "").trim()
        : "";

      if (!from || !/^0x[a-fA-F0-9]{40}$/.test(from)) {
        setPre("voidSendOut", { ok:false, error:"wallet_not_connected" });
        setLatestAction("VOID send unavailable. Unlock the participant wallet first.");
        return;
      }
      if (!to || !/^0x[a-fA-F0-9]{40}$/.test(to)) {
        setPre("voidSendOut", { ok:false, error:"invalid_recipient_wallet" });
        setLatestAction("Enter a valid recipient wallet before sending VOID.");
        return;
      }

      let units;
      try {
        units = parseUnits18(amountStr);
      } catch (_) {
        setPre("voidSendOut", { ok:false, error:"invalid_amount" });
        setLatestAction("Enter a valid VOID amount before sending.");
        return;
      }
      if (!(units > 0n)) {
        setPre("voidSendOut", { ok:false, error:"invalid_amount" });
        setLatestAction("Enter a VOID amount greater than zero.");
        return;
      }

      const relayerHealth = await j(LOCAL_RELAYER_BASE + "/health");
      const voidToken = relayerHealth && relayerHealth.ok ? String(relayerHealth.void_token || "").trim() : "";
      if (!/^0x[a-fA-F0-9]{40}$/.test(voidToken)) {
        setPre("voidSendOut", { ok:false, error:"void_token_unavailable", relayer_health: relayerHealth });
        setLatestAction("VOID send unavailable right now. Token metadata could not be loaded.");
        return;
      }

      const nativeStatus = await j("/__void/participant/wallet/status?account=" + encodeURIComponent(resolveActiveParticipantAccount())).catch(() => ({ ok:false }));
      if (nativeStatus && nativeStatus.ok && nativeStatus.unlocked && /^0x[a-fA-F0-9]{40}$/.test(String(nativeStatus.address || "")) && String(nativeStatus.address).toLowerCase() === String(from).toLowerCase()) {
        if (btn) {
          btn.disabled = true;
          btn.textContent = "Sending...";
        }

        setLatestAction("Sending " + amountStr + " VOID to " + shortAddr(to) + " from participant wallet...");
        setWalletActivity({ kind:"send_void", status:"submitting", amount:amountStr, unit:"VOID", target:shortAddr(to) });
        setPre("voidSendOut", {
          ok:true,
          submitting:true,
          from,
          to,
          void_token: voidToken,
          amount: amountStr,
          mode: "participant_wallet_native_send_void"
        });

        const nativeOut = await j("/__void/participant/wallet/send-void", {
          method: "POST",
          headers: { "content-type":"application/json" },
          body: JSON.stringify({ account: resolveActiveParticipantAccount(), to, amount: amountStr })
        });

        if (!(nativeOut && nativeOut.ok)) {
          setPre("voidSendOut", nativeOut || { ok:false, error:"native_send_void_failed" });
          setLatestAction("VOID send failed • " + String((nativeOut && (nativeOut.error || nativeOut.reason || nativeOut.note)) || "participant wallet send failed"));
          return;
        }

        const txHash = String(nativeOut.tx_hash || "");
        const shortHash = /^0x[a-fA-F0-9]{64}$/.test(txHash) ? (txHash.slice(0, 10) + "…" + txHash.slice(-6)) : String(txHash || "-");

        setPre("voidSendOut", nativeOut);
        setLatestAction("VOID send submitted • " + amountStr + " VOID to " + shortAddr(to) + " • tx " + shortHash);
        setWalletActivity({ kind:"send_void", status:"sent", amount:amountStr, unit:"VOID", target:shortAddr(to), tx_hash:txHash });

        if (toInput) toInput.value = "";
        if (amountInput) amountInput.value = "1";

        await refresh();
        return;
      }

      if (!window.ethereum || !window.ethereum.request) {
        setPre("voidSendOut", { ok:false, error:"wallet_provider_missing" });
        setLatestAction("VOID send unavailable. Wallet provider missing.");
        return;
      }

      if (btn) {
        btn.disabled = true;
        btn.textContent = "Sending...";
      }

      const tx = {
        from: from,
        to: voidToken,
        data: erc20TransferData(to, units)
      };

      setLatestAction("Sending " + amountStr + " VOID to " + shortAddr(to) + "...");
      setWalletActivity({ kind:"send_void", status:"submitting", amount:amountStr, unit:"VOID", target:shortAddr(to) });
      setPre("voidSendOut", {
        ok:true,
        submitting:true,
        from,
        to,
        void_token: voidToken,
        amount: amountStr,
        tx
      });

      const txHash = await window.ethereum.request({
        method: "eth_sendTransaction",
        params: [tx]
      });

      const shortHash = /^0x[a-fA-F0-9]{64}$/.test(String(txHash || "")) ? (String(txHash).slice(0, 10) + "…" + String(txHash).slice(-6)) : String(txHash || "-");

      setPre("voidSendOut", {
        ok:true,
        sent:true,
        from,
        to,
        void_token: voidToken,
        amount: amountStr,
        tx_hash: txHash,
        note: "VOID transfer submitted from stored execution wallet."
      });
      setLatestAction("VOID send submitted • " + amountStr + " VOID to " + shortAddr(to) + " • tx " + shortHash);
      setWalletActivity({ kind:"send_void", status:"sent", amount:amountStr, unit:"VOID", target:shortAddr(to), tx_hash:txHash });

      if (toInput) toInput.value = "";
      if (amountInput) amountInput.value = "1";

      await refresh();
    } catch (e) {
      const err = String((e && e.message) || e);
      setPre("voidSendOut", { ok:false, error:err });
      setLatestAction("VOID send failed • " + err);
      setWalletActivity({ kind:"send_void", status:"failed", amount:amountStr, unit:"VOID", target:shortAddr(to), note:err });
    } finally {
      if (btn) {
        btn.disabled = false;
        btn.textContent = prevText || "Send VOID";
      }
    }
  }

  async function submitJob(){
    const account = resolveActiveParticipantAccount();
    const plaintext = $("plaintext") ? $("plaintext").value : "";
    const btn = $("submitBtn");
    if (btn) btn.disabled = true;

    let redeemableBefore = 0;
    try {
      const st0 = await j("/wc/redeemable?account=" + encodeURIComponent(account));
      redeemableBefore = st0 && st0.ok ? Number(st0.redeemable || 0) : 0;
    } catch (_) { voidIndexEmptyCatchVisibilityWindow59401_78300V1("73364:182", _); }

    setPre("submitOut", { ok:true, submitting:true, account, redeemable_before: redeemableBefore });

    try {
      const out = await j("/jobs/submit", {
        method: "POST",
        headers: { "content-type":"application/json" },
        body: JSON.stringify({ account, kind:"datanet_publish", plaintext })
      });
      setPre("submitOut", out);
      const jobId = out && out.job && out.job.job_id ? String(out.job.job_id) : "";
      const jobShort = jobId && jobId.length > 24 ? (jobId.slice(0, 10) + "…" + jobId.slice(-6)) : jobId;

      if (out && out.ok && jobId) {
        setLatestAction("Work submitted • Job " + jobShort + " • Waiting for completion and WC credit.");
        setPre("submitOut", {
          ...out,
          note: "Work submitted • Job " + jobId + " • Waiting for completion and WC credit.",
          redeemable_before: redeemableBefore
        });
      }

      if (jobId) {
        for (let i = 0; i < 8; i++) {
          await new Promise(r => setTimeout(r, 1500));
          const st = await j("/jobs/" + encodeURIComponent(jobId));
          setPre("submitOut", st);

          if (st && st.job && st.job.status === "completed") {
            setLatestAction("Work completed • Job " + jobShort + " • Waiting for WC credit to appear.");
            setPre("submitOut", {
              ...st,
              note: "Work completed • Job " + jobId + " • Waiting for WC credit to appear.",
              credit_pending_check: true,
              redeemable_before: redeemableBefore
            });

            const creditWait = await waitForRedeemableIncrease(account, redeemableBefore, 12000);
            const beforeAmt = creditWait && Number.isFinite(Number(creditWait.before_redeemable)) ? Number(creditWait.before_redeemable) : redeemableBefore;
            const afterAmt = creditWait && Number.isFinite(Number(creditWait.after_redeemable)) ? Number(creditWait.after_redeemable) : redeemableBefore;

            setLatestAction(
              creditWait && creditWait.ok
                ? ("Work completed • Job " + jobShort + " • WC visible now (" + beforeAmt + " → " + afterAmt + ").")
                : ("Work completed • Job " + jobShort + " • WC not visible before timeout (" + beforeAmt + " → " + afterAmt + ").")
            );
            setPre("submitOut", {
              ...st,
              credit_wait: creditWait,
              note: creditWait && creditWait.ok
                ? ("Work completed • Job " + jobId + " • WC visible now (" + beforeAmt + " -> " + afterAmt + ").")
                : ("Work completed • Job " + jobId + " • WC not visible before timeout (" + beforeAmt + " -> " + afterAmt + ")."),
              redeemable_before: beforeAmt,
              redeemable_after: afterAmt
            });
            break;
          }

          if (st && st.job && st.job.status === "failed") {
            setLatestAction("Work failed • Job " + jobShort + " • Check the job status below.");
            setPre("submitOut", {
              ...st,
              note: "Work failed • Job " + jobId + " • Check the job status below."
            });
            break;
          }
        }
      }
    } catch (e) {
      setPre("submitOut", { ok:false, error:String(e) });
    } finally {
      if (btn) btn.disabled = false;
      await refresh();
    }
  }

