// ---------------- [ADD] Agent candidate freshness routes/exporter ----------------
(function AgentCandidateFreshnessRoutes(){
  try{
    const TICK = 400;

    function mount(){
      const g:any = globalThis as any;
      const APP:any = g.__void_http_app || g.app;
      if (!APP || typeof APP.get !== "function") return setTimeout(mount, TICK);
      if ((APP as any).__void_agent_candidate_freshness_v1__) return;
      (APP as any).__void_agent_candidate_freshness_v1__ = true;

      function dataDirLocal(){
        return String(process.env.DATA_DIR || "data_a");
      }

      function runnerDatanetDirLocal(){
        const path = require("node:path");
        return path.join(dataDirLocal(), "datanet_v1", "local_jobs");
      }

      function candidateSnapshot(account:string){
        const fs = require("node:fs");
        const path = require("node:path");
        const dir = runnerDatanetDirLocal();
        const now = Date.now();
        const verifyCooldownMs = 5 * 60 * 1000;
        const redundancyCooldownMs = 15 * 60 * 1000;
        const MAX_PICK_STALE_MS = Math.max(60000, Number(process.env.VOID_AGENT_MAX_STALE_MS || 7 * 24 * 60 * 60 * 1000));

        const rt:any = (globalThis as any).__void_wc_runner_runtime_v1 || {};
        rt.verify_history_by_dataset = rt.verify_history_by_dataset || {};
        rt.redundancy_history_by_dataset = rt.redundancy_history_by_dataset || {};

        const out:any[] = [];
        if (!fs.existsSync(dir)) {
          return {
            ok: true,
            account,
            dir,
            verify_candidate: null,
            redundancy_candidate: null,
            counts: {
              total_datasets: 0,
              verify_eligible: 0,
              verify_over_stale: 0,
              redundancy_eligible: 0,
              redundancy_over_stale: 0
            },
            items: []
          };
        }

        const files = fs.readdirSync(dir)
          .filter((x:any) => String(x).endsWith(".txt"))
          .sort();

        let verifyEligible = 0;
        let verifyOverStale = 0;
        let redundancyEligible = 0;
        let redundancyOverStale = 0;

        let verifyCandidate:any = null;
        let verifyChosenTs = Number.POSITIVE_INFINITY;

        let redundancyCandidate:any = null;
        let redundancyChosenTs = Number.POSITIVE_INFINITY;

        for (const f of files) {
          const datasetId = String(f).replace(/\.txt$/i, "");
          const fullPath = path.join(dir, f);

          let fileMtimeMs = 0;
          try { fileMtimeMs = Number(fs.statSync(fullPath).mtimeMs || 0); } catch (err) { voidIndexEmptyCatchVisibilityWindow59401_78300V1("76578:277", err); }

          const verifyLast = Number((rt.verify_history_by_dataset[String(account)] || {})[datasetId] || 0);
          const verifyBasis = verifyLast > 0 ? verifyLast : fileMtimeMs;
          const verifyAge = verifyBasis > 0 ? (now - verifyBasis) : (2 * 60 * 60 * 1000);
          const verifyEligibleNow = verifyAge >= verifyCooldownMs && verifyAge <= MAX_PICK_STALE_MS;

          const redundancyLast = Number((rt.redundancy_history_by_dataset[String(account)] || {})[datasetId] || 0);
          const redundancyBasis = redundancyLast > 0 ? redundancyLast : fileMtimeMs;
          const redundancyAge = redundancyBasis > 0 ? (now - redundancyBasis) : (8 * 60 * 60 * 1000);
          const redundancyEligibleNow = redundancyAge >= redundancyCooldownMs && redundancyAge <= MAX_PICK_STALE_MS;

          if (verifyEligibleNow) verifyEligible += 1;
          if (verifyAge > MAX_PICK_STALE_MS) verifyOverStale += 1;
          if (redundancyEligibleNow) redundancyEligible += 1;
          if (redundancyAge > MAX_PICK_STALE_MS) redundancyOverStale += 1;

          if (verifyEligibleNow && verifyBasis < verifyChosenTs) {
            verifyChosenTs = verifyBasis;
            verifyCandidate = {
              dataset_id: datasetId,
              path: fullPath,
              last_verified_ms: verifyLast || null,
              file_mtime_ms: fileMtimeMs || null,
              stale_for_ms: verifyAge
            };
          }

          if (redundancyEligibleNow && redundancyBasis < redundancyChosenTs) {
            redundancyChosenTs = redundancyBasis;
            redundancyCandidate = {
              dataset_id: datasetId,
              path: fullPath,
              last_redundancy_check_ms: redundancyLast || null,
              file_mtime_ms: fileMtimeMs || null,
              stale_for_ms: redundancyAge
            };
          }

          out.push({
            dataset_id: datasetId,
            path: fullPath,
            file_mtime_ms: fileMtimeMs || null,
            verify: {
              last_ms: verifyLast || null,
              stale_for_ms: verifyAge,
              cooldown_ms: verifyCooldownMs,
              eligible: !!verifyEligibleNow,
              over_stale_cap: verifyAge > MAX_PICK_STALE_MS
            },
            redundancy: {
              last_ms: redundancyLast || null,
              stale_for_ms: redundancyAge,
              cooldown_ms: redundancyCooldownMs,
              eligible: !!redundancyEligibleNow,
              over_stale_cap: redundancyAge > MAX_PICK_STALE_MS
            }
          });
        }

        out.sort((a:any, b:any) => {
          const aFreshEligible = ((a?.verify?.eligible && !a?.verify?.over_stale_cap) || (a?.redundancy?.eligible && !a?.redundancy?.over_stale_cap)) ? 1 : 0;
          const bFreshEligible = ((b?.verify?.eligible && !b?.verify?.over_stale_cap) || (b?.redundancy?.eligible && !b?.redundancy?.over_stale_cap)) ? 1 : 0;
          if (bFreshEligible !== aFreshEligible) return bFreshEligible - aFreshEligible;

          const aStale = Math.min(
            Number.isFinite(Number(a?.verify?.stale_for_ms)) ? Number(a?.verify?.stale_for_ms) : Number.POSITIVE_INFINITY,
            Number.isFinite(Number(a?.redundancy?.stale_for_ms)) ? Number(a?.redundancy?.stale_for_ms) : Number.POSITIVE_INFINITY
          );
          const bStale = Math.min(
            Number.isFinite(Number(b?.verify?.stale_for_ms)) ? Number(b?.verify?.stale_for_ms) : Number.POSITIVE_INFINITY,
            Number.isFinite(Number(b?.redundancy?.stale_for_ms)) ? Number(b?.redundancy?.stale_for_ms) : Number.POSITIVE_INFINITY
          );
          return aStale - bStale;
        });

        const freshVerifyCandidate =
          out.find((x:any) => x?.verify?.eligible && !x?.verify?.over_stale_cap) ||
          verifyCandidate || null;

        const freshRedundancyCandidate =
          out.find((x:any) => x?.redundancy?.eligible && !x?.redundancy?.over_stale_cap) ||
          redundancyCandidate || null;

        return {
          ok: true,
          account,
          dir,
          verify_candidate: freshVerifyCandidate,
          redundancy_candidate: freshRedundancyCandidate,
          counts: {
            total_datasets: out.length,
            verify_eligible: verifyEligible,
            verify_over_stale: verifyOverStale,
            redundancy_eligible: redundancyEligible,
            redundancy_over_stale: redundancyOverStale
          },
          items: out.slice(0, 200)
        };
      }

      APP.get("/__void/agent/candidates.v1", (req:any, res:any) => {
        try{
          const account = String(req?.query?.account || "dev-zoso");
          return res.json(candidateSnapshot(account));
        }catch(e:any){
          return res.status(500).json({ ok:false, error:String(e?.message || e) });
        }
      });

      APP.get("/__void/metrics/agent_candidates.prom", (req:any, res:any) => {
        try{
          const account = String(req?.query?.account || "dev-zoso");
          const snap:any = candidateSnapshot(account);
          const vc = snap?.verify_candidate || null;
          const rc = snap?.redundancy_candidate || null;
          const counts:any = snap?.counts || {};

          const esc = (x:any) => String(x ?? "").replace(/\\/g, "\\\\").replace(/"/g, '\\"');

          const lines = [
            "# HELP void_agent_candidates_verify_eligible_total Verify candidates currently eligible",
            "# TYPE void_agent_candidates_verify_eligible_total gauge",
            "void_agent_candidates_verify_eligible_total{account=\"" + esc(account) + "\"} " + Number(counts.verify_eligible || 0),

            "# HELP void_agent_candidates_verify_over_stale_total Verify candidates over stale cap",
            "# TYPE void_agent_candidates_verify_over_stale_total gauge",
            "void_agent_candidates_verify_over_stale_total{account=\"" + esc(account) + "\"} " + Number(counts.verify_over_stale || 0),

            "# HELP void_agent_candidates_redundancy_eligible_total Redundancy candidates currently eligible",
            "# TYPE void_agent_candidates_redundancy_eligible_total gauge",
            "void_agent_candidates_redundancy_eligible_total{account=\"" + esc(account) + "\"} " + Number(counts.redundancy_eligible || 0),

            "# HELP void_agent_candidates_redundancy_over_stale_total Redundancy candidates over stale cap",
            "# TYPE void_agent_candidates_redundancy_over_stale_total gauge",
            "void_agent_candidates_redundancy_over_stale_total{account=\"" + esc(account) + "\"} " + Number(counts.redundancy_over_stale || 0),

            "# HELP void_agent_candidates_verify_candidate_stale_ms Current chosen verify candidate stale_for_ms",
            "# TYPE void_agent_candidates_verify_candidate_stale_ms gauge",
            "void_agent_candidates_verify_candidate_stale_ms{account=\"" + esc(account) + "\",dataset_id=\"" + esc(vc?.dataset_id || "") + "\"} " + Number(vc?.stale_for_ms || 0),

            "# HELP void_agent_candidates_redundancy_candidate_stale_ms Current chosen redundancy candidate stale_for_ms",
            "# TYPE void_agent_candidates_redundancy_candidate_stale_ms gauge",
            "void_agent_candidates_redundancy_candidate_stale_ms{account=\"" + esc(account) + "\",dataset_id=\"" + esc(rc?.dataset_id || "") + "\"} " + Number(rc?.stale_for_ms || 0)
          ];

          return res.type("text/plain; version=0.0.4; charset=utf-8").send(lines.join("\\n") + "\n");
        }catch(e:any){
          return res.type("text/plain; version=0.0.4; charset=utf-8").send(
            "# HELP void_agent_candidates_exporter_error exporter error\n" +
            "# TYPE void_agent_candidates_exporter_error gauge\n" +
            "void_agent_candidates_exporter_error 1\n"
          );
        }
      });

      try { console.log("[agent.candidates.v1] mounted: /__void/agent/candidates.v1 and /__void/metrics/agent_candidates.prom"); } catch (err) { voidIndexEmptyCatchVisibilityWindow59401_78300V1("76734:278", err); }
    }

    mount();
  }catch (err) { voidIndexEmptyCatchVisibilityWindow59401_78300V1("76738:279", err); }
})();


// ---------------- [ADD] Agent receipts truth exporter v2 (last-wins) ----------------
(function AgentReceiptsTruthExporterV2(){
  try{
    const TICK = 400;

    function mount(){
      const g:any = globalThis as any;
      const app:any = g.__void_http_app || g.app;
      if (!app || typeof app.get !== "function") return setTimeout(mount, TICK);
      if ((app as any).__agent_receipts_truth_exporter_v2__) return;
      (app as any).__agent_receipts_truth_exporter_v2__ = true;

      const fs = require("node:fs");
      const path = require("node:path");

      function dataDir(){
        return String(process.env.DATA_DIR || process.env.VOID_DATA_DIR || "data_a");
      }
      function receiptsFile(){
        return path.join(dataDir(), "agent_v1", "receipts.jsonl");
      }
      function resultsFile(){
        return path.join(dataDir(), "agent_v1", "job_state.jsonl");
      }
      function ledgerFile(){
        return path.join(dataDir(), "wc_v1", "ledger.jsonl");
      }

      function safeReadLines(file:string, maxLines:number=20000){
        try{
          if (!fs.existsSync(file)) return [];
          const raw = String(fs.readFileSync(file, "utf8") || "");
          const lines = raw.split(/\r?\n/).filter(Boolean);
          return lines.slice(-maxLines);
        }catch{
          return [];
        }
      }

      function safeJsonLines(file:string, maxLines:number=20000){
        const out:any[] = [];
        for (const line of safeReadLines(file, maxLines)){
          try{
            const j = JSON.parse(line);
            if (j && typeof j === "object") out.push(j);
          }catch (err) { voidIndexEmptyCatchVisibilityWindow59401_78300V1("76787:280", err); }
        }
        return out;
      }

      function computeTruth(){
        const recs = safeJsonLines(receiptsFile(), 50000);
        const resu = safeJsonLines(resultsFile(), 50000);
        const ledg = safeJsonLines(ledgerFile(), 50000);

        const recIds = new Set<string>();
        let receiptsLastTsMs = 0;
        let nonAgentReceiptLastTsMs = 0;
        let uniq5 = new Set<string>();
        let uniq15 = new Set<string>();
        const now = Date.now();
        const since5 = now - (5 * 60 * 1000);
        const since15 = now - (15 * 60 * 1000);

        for (const r of recs){
          const id = String(r?.job_id || r?.id || r?.receipt_id || "");
          if (id) recIds.add(id);
          const ts = Number(r?.ts_ms || 0);
          if (ts > receiptsLastTsMs) receiptsLastTsMs = ts;

          const account = String(r?.account || "");
          const kind = String(r?.kind || r?.receipt_kind || "");
          const isAgentish = account.startsWith("agent:") || kind.startsWith("agent:");
          if (!isAgentish && ts > nonAgentReceiptLastTsMs) nonAgentReceiptLastTsMs = ts;

          if (id && ts >= since5) uniq5.add(id);
          if (id && ts >= since15) uniq15.add(id);
        }

        const resultIds = new Set<string>();
        for (const r of resu){
          const id = String(r?.id || r?.job_id || "");
          if (id) resultIds.add(id);
        }

        let covered = 0;
        for (const id of resultIds){
          if (recIds.has(id)) covered += 1;
        }

        let wcAwardedTotal = 0;
        let wcAwardsLastTsMs = 0;
        for (const l of ledg){
          if (String(l?.kind || "") !== "credit") continue;
          const delta = Number(l?.delta || 0) || 0;
          wcAwardedTotal += delta;
          const ts = Number(l?.ts_ms || 0);
          if (ts > wcAwardsLastTsMs) wcAwardsLastTsMs = ts;
        }

        const receiptsAgeSec = receiptsLastTsMs > 0 ? Math.max(0, (now - receiptsLastTsMs) / 1000) : 1e12;
        const wcAgeSec = wcAwardsLastTsMs > 0 ? Math.max(0, (now - wcAwardsLastTsMs) / 1000) : 1e12;

        return {
          results_total: resultIds.size,
          receipts_total: recIds.size,
          receipts_covered: covered,
          receipts_coverage: resultIds.size > 0 ? (covered / resultIds.size) : (recIds.size > 0 ? 1 : 0),
          receipts_last_ts_ms: receiptsLastTsMs,
          receipts_age_seconds: receiptsAgeSec,
          wc_awarded_total: wcAwardedTotal,
          wc_awards_last_ts_seconds: wcAwardsLastTsMs > 0 ? (wcAwardsLastTsMs / 1000) : 0,
          wc_awards_age_seconds: wcAgeSec,
          wc_awards_unique_5m: uniq5.size,
          wc_awards_ok_5m: uniq5.size > 0 && wcAgeSec < 10 * 60 ? 1 : 0,
          wc_awards_unique_15m: uniq15.size,
          wc_awards_ok_15m: uniq15.size > 0 && wcAgeSec < 20 * 60 ? 1 : 0
        };
      }

      app.get("/__void/metrics/agent_receipts.prom", (_req:any, res:any)=>{
        try{
          const t = computeTruth();
          const lines = [
            "# HELP void_agent_receipts_total total unique receipts observed",
            "# TYPE void_agent_receipts_total gauge",
            `void_agent_receipts_total ${t.receipts_total}`,
            "# HELP void_agent_receipts_errors total receipt write errors (truth exporter does not track legacy counter; 0 by default)",
            "# TYPE void_agent_receipts_errors gauge",
            "void_agent_receipts_errors 0",
            "# HELP void_agent_receipts_last_ts_ms latest receipt timestamp ms",
            "# TYPE void_agent_receipts_last_ts_ms gauge",
            `void_agent_receipts_last_ts_ms ${t.receipts_last_ts_ms}`,
            "# HELP void_agent_receipts_age_seconds seconds since latest receipt",
            "# TYPE void_agent_receipts_age_seconds gauge",
            `void_agent_receipts_age_seconds ${t.receipts_age_seconds}`
          ];
          return res.type("text/plain; version=0.0.4; charset=utf-8").send(lines.join("\\n") + "\n");
        }catch(e:any){
          return res.status(500).type("text/plain; version=0.0.4; charset=utf-8").send("void_agent_receipts_errors 1\n");
        }
      });

      app.get("/__void/metrics/agent_receipts_coverage.prom", (_req:any, res:any)=>{
        try{
          const t = computeTruth();
          const lines = [
            "# HELP void_agent_results_unique_total total unique job results observed",
            "# TYPE void_agent_results_unique_total gauge",
            `void_agent_results_unique_total ${t.results_total}`,
            "# HELP void_agent_receipts_total total receipts observed (unique ids)",
            "# TYPE void_agent_receipts_total gauge",
            `void_agent_receipts_total ${t.receipts_total}`,
            "# HELP void_agent_receipts_covered results with corresponding receipts",
            "# TYPE void_agent_receipts_covered gauge",
            `void_agent_receipts_covered ${t.receipts_covered}`,
            "# HELP void_agent_receipts_coverage fraction of results with receipts (0..1)",
            "# TYPE void_agent_receipts_coverage gauge",
            `void_agent_receipts_coverage ${t.receipts_coverage}`
          ];
          return res.type("text/plain; version=0.0.4; charset=utf-8").send(lines.join("\\n") + "\n");
        }catch(e:any){
          return res.status(500).type("text/plain; version=0.0.4; charset=utf-8").send("void_agent_receipts_coverage 0\n");
        }
      });

      app.get("/__void/metrics/agent_wc_awards.prom", (_req:any, res:any)=>{
        try{
          const t = computeTruth();
          const lines = [
            "# HELP void_agent_wc_awarded_total cumulative WC credits from ledger credits",
            "# TYPE void_agent_wc_awarded_total gauge",
            `void_agent_wc_awarded_total ${t.wc_awarded_total}`,
            "# HELP void_agent_wc_awards_last_ts_seconds last credit timestamp seen (seconds)",
            "# TYPE void_agent_wc_awards_last_ts_seconds gauge",
            `void_agent_wc_awards_last_ts_seconds ${t.wc_awards_last_ts_seconds}`,
            "# HELP void_agent_wc_awards_age_seconds seconds since last credit",
            "# TYPE void_agent_wc_awards_age_seconds gauge",
            `void_agent_wc_awards_age_seconds ${t.wc_awards_age_seconds}`,
            "# HELP void_agent_wc_awards_unique_5m unique receipt ids in last 5m",
            "# TYPE void_agent_wc_awards_unique_5m gauge",
            `void_agent_wc_awards_unique_5m ${t.wc_awards_unique_5m}`,
            "# HELP void_agent_wc_awards_ok_5m 1 if unique_5m>0 and age<10m",
            "# TYPE void_agent_wc_awards_ok_5m gauge",
            `void_agent_wc_awards_ok_5m ${t.wc_awards_ok_5m}`,
            "# HELP void_agent_wc_awards_unique_15m unique receipt ids in last 15m",
            "# TYPE void_agent_wc_awards_unique_15m gauge",
            `void_agent_wc_awards_unique_15m ${t.wc_awards_unique_15m}`,
            "# HELP void_agent_wc_awards_ok_15m 1 if unique_15m>0 and age<20m",
            "# TYPE void_agent_wc_awards_ok_15m gauge",
            `void_agent_wc_awards_ok_15m ${t.wc_awards_ok_15m}`
          ];
          return res.type("text/plain; version=0.0.4; charset=utf-8").send(lines.join("\\n") + "\n");
        }catch(e:any){
          return res.status(500).type("text/plain; version=0.0.4; charset=utf-8").send("void_agent_wc_awarded_total 0\n");
        }
      });

      try{ console.log("[agent.receipts.truth.v2] mounted"); }catch (err) { voidIndexEmptyCatchVisibilityWindow59401_78300V1("76940:281", err); }
    }

    mount();
  }catch (err) { voidIndexEmptyCatchVisibilityWindow59401_78300V1("76944:282", err); }
})();


